请用 TypeScript 帮我重构下面这段函数，让它清晰可维护。

```typescript
function processOrder(order) {
    var result = {};
    if (order) {
        if (order.items && order.items.length > 0) {
            var total = 0;
            for (var i = 0; i < order.items.length; i++) {
                var item = order.items[i];
                if (item.price && item.quantity) {
                    total += item.price * item.quantity;
                }
            }
            if (total > 0) {
                if (order.customer && order.customer.vip) {
                    total = total * 0.9;
                }
                if (total > 1000) {
                    total = total - 50;
                }
                result.total = total;
                result.status = 'processed';
                console.log('Order processed: ' + order.id + ', total: ' + total);
                saveToDatabase(order, result);
                sendEmail(order.customer.email, 'Your order has been processed');
            }
        }
    }
    return result;
}
```

